def longest(words):
    best = words[0]
    for word in words:
        if len(word) > len(best):
            best = word
    return best

def count_unique(items):
    seen = []
    for item in items:
        if item not in seen:
            seen.append(item)
    return len(seen)

def swap(pair):
    a, b = pair
    return b, a

